const express = require('express');
const { jwtVerify, importSPKI } = require('jose');
const fs = require('fs');

const app = express();
const PUBLIC_KEY_PEM = fs.readFileSync(process.env.JWT_PUBLIC_KEY_PATH, 'utf8');

const verifyTokenMiddleware = async (req, res, next) => {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing bearer token' });
  }

  const token = authHeader.split(' ')[1];
  try {
    const publicKey = await importSPKI(PUBLIC_KEY_PEM, 'RS256');
    // Enforce RS256 algorithm restriction and validate issuer/audience
    const { payload } = await jwtVerify(token, publicKey, {
      algorithms: ['RS256'],
      issuer: 'https://auth.ledgercloud.io'
    });
    req.auth = payload;
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid token signature' });
  }
};

app.get('/api/organizations/:orgId/financial-records', verifyTokenMiddleware, async (req, res) => {
  const { orgId } = req.params;

  // Validate organization membership against token claims
  if (req.auth.orgId !== orgId) {
    return res.status(403).json({ error: 'Forbidden: token not authorized for this organization' });
  }

  const records = await fetchOrgFinancials(orgId);
  return res.json({ orgId, records });
});

module.exports = app;
